def decode(string):
    result = []
    count = ""

    for char in string:
        if char.isdigit():
            count += char
        else:
            repeat = int(count) if count else 1
            result.append(char * repeat)
            count = ""

    return "".join(result)


def encode(string):
    if not string:
        return ""

    result = []
    current = string[0]
    count = 1

    for char in string[1:]:
        if char == current:
            count += 1
        else:
            if count > 1:
                result.append(str(count))
            result.append(current)
            current = char
            count = 1

    if count > 1:
        result.append(str(count))
    result.append(current)

    return "".join(result)
